import * as $g from "../glance/glance.mjs";
import * as $option from "../gleam_stdlib/gleam/option.mjs";
import { Ok } from "./gleam.mjs";
import * as $builtins from "./gloat/builtins.mjs";
import * as $env from "./gloat/env.mjs";
import * as $env_json from "./gloat/env_json.mjs";
import * as $gloat_glance from "./gloat/glance.mjs";
import * as $infer from "./gloat/infer.mjs";
import * as $is from "./gloat/infer_state.mjs";
import * as $scheme from "./gloat/scheme.mjs";
import * as $type_error from "./gloat/type_error.mjs";
import * as $types from "./gloat/types.mjs";

export function builtin_env() {
  return $builtins.builtin_env();
}

export function add_module(tenv, module) {
  return $builtins.add_module(tenv, module, "");
}

export function resolve(tenv, name) {
  let $ = $env.resolve(tenv, name);
  if ($ instanceof Ok) {
    let scheme = $[0];
    return new $option.Some(scheme);
  } else {
    return new $option.None();
  }
}

export function add_module_with_target(tenv, module, target, module_key) {
  return $builtins.add_module(
    tenv,
    $gloat_glance.filter_module_for_target(module, target),
    module_key,
  );
}

export function infer_expr(tenv, expr) {
  return $is.run_empty($infer.infer_expr(tenv, expr));
}

export function type_to_string_debug(type_) {
  return $types.type_to_string(type_);
}

export function type_to_string(type_) {
  return $types.type_to_string_gleam(type_);
}

export function scheme_to_string_debug(scheme_) {
  return $scheme.scheme_to_string(scheme_);
}

export function scheme_to_string(scheme_) {
  return $scheme.scheme_to_string_gleam(scheme_);
}

export function tenv_to_json(tenv) {
  return $env_json.encode(tenv);
}

export function tenv_from_json(input) {
  return $env_json.decode(input);
}
