import { CustomType as $CustomType, makeError } from "../gleam.mjs";
import * as $ranges from "../pubgrub/version_ranges.mjs";

const FILEPATH = "src/pubgrub/term.gleam";

export class Positive extends $CustomType {
  constructor($0) {
    super();
    this[0] = $0;
  }
}
export const Term$Positive = ($0) => new Positive($0);
export const Term$isPositive = (value) => value instanceof Positive;
export const Term$Positive$0 = (value) => value[0];

export class Negative extends $CustomType {
  constructor($0) {
    super();
    this[0] = $0;
  }
}
export const Term$Negative = ($0) => new Negative($0);
export const Term$isNegative = (value) => value instanceof Negative;
export const Term$Negative$0 = (value) => value[0];

export class Satisfied extends $CustomType {}
export const Relation$Satisfied = () => new Satisfied();
export const Relation$isSatisfied = (value) => value instanceof Satisfied;

export class Contradicted extends $CustomType {}
export const Relation$Contradicted = () => new Contradicted();
export const Relation$isContradicted = (value) => value instanceof Contradicted;

export class Inconclusive extends $CustomType {}
export const Relation$Inconclusive = () => new Inconclusive();
export const Relation$isInconclusive = (value) => value instanceof Inconclusive;

/**
 * A term that accepts any version.
 */
export function any(compare) {
  return new Negative($ranges.empty(compare));
}

/**
 * A term that accepts no versions.
 */
export function empty(compare) {
  return new Positive($ranges.empty(compare));
}

/**
 * A term that accepts exactly one version.
 */
export function exact(compare, version) {
  return new Positive($ranges.singleton(compare, version));
}

/**
 * Extract the compare function carried by a term.
 */
export function compare(term) {
  if (term instanceof Positive) {
    let set = term[0];
    return $ranges.compare(set);
  } else {
    let set = term[0];
    return $ranges.compare(set);
  }
}

/**
 * True when the term allows all versions.
 */
export function is_any(term) {
  if (term instanceof Positive) {
    return false;
  } else {
    let set = term[0];
    return $ranges.is_empty(set);
  }
}

/**
 * True when two terms have the same polarity and range set.
 */
export function equal(left, right) {
  if (left instanceof Positive) {
    if (right instanceof Positive) {
      let l = left[0];
      let r = right[0];
      return $ranges.equal(l, r);
    } else {
      return false;
    }
  } else if (right instanceof Negative) {
    let l = left[0];
    let r = right[0];
    return $ranges.equal(l, r);
  } else {
    return false;
  }
}

/**
 * True for positive terms.
 */
export function is_positive(term) {
  if (term instanceof Positive) {
    return true;
  } else {
    return false;
  }
}

/**
 * Flip a term from positive to negative (or vice versa).
 */
export function negate(term) {
  if (term instanceof Positive) {
    let set = term[0];
    return new Negative(set);
  } else {
    let set = term[0];
    return new Positive(set);
  }
}

/**
 * Check whether a version is allowed by the term.
 */
export function contains(term, version) {
  if (term instanceof Positive) {
    let set = term[0];
    return $ranges.contains(set, version);
  } else {
    let set = term[0];
    return !$ranges.contains(set, version);
  }
}

/**
 * Extract the positive range set or panic.
 */
export function unwrap_positive(term) {
  if (term instanceof Positive) {
    let set = term[0];
    return set;
  } else {
    throw makeError(
      "panic",
      FILEPATH,
      "pubgrub/term",
      86,
      "unwrap_positive",
      "unwrap_positive called on negative term",
      {}
    )
  }
}

/**
 * Extract the negative range set or panic.
 */
export function unwrap_negative(term) {
  if (term instanceof Positive) {
    throw makeError(
      "panic",
      FILEPATH,
      "pubgrub/term",
      94,
      "unwrap_negative",
      "unwrap_negative called on positive term",
      {}
    )
  } else {
    let set = term[0];
    return set;
  }
}

/**
 * Intersection of two terms.
 */
export function intersection(left, right) {
  if (left instanceof Positive) {
    if (right instanceof Positive) {
      let r1 = left[0];
      let r2 = right[0];
      return new Positive($ranges.intersection(r1, r2));
    } else {
      let p = left[0];
      let n = right[0];
      return new Positive($ranges.intersection($ranges.complement(n), p));
    }
  } else if (right instanceof Positive) {
    let n = left[0];
    let p = right[0];
    return new Positive($ranges.intersection($ranges.complement(n), p));
  } else {
    let r1 = left[0];
    let r2 = right[0];
    return new Negative($ranges.union(r1, r2));
  }
}

/**
 * Union of two terms.
 */
export function union(left, right) {
  if (left instanceof Positive) {
    if (right instanceof Positive) {
      let r1 = left[0];
      let r2 = right[0];
      return new Positive($ranges.union(r1, r2));
    } else {
      let p = left[0];
      let n = right[0];
      return new Negative($ranges.intersection($ranges.complement(p), n));
    }
  } else if (right instanceof Positive) {
    let n = left[0];
    let p = right[0];
    return new Negative($ranges.intersection($ranges.complement(p), n));
  } else {
    let r1 = left[0];
    let r2 = right[0];
    return new Negative($ranges.intersection(r1, r2));
  }
}

/**
 * True if two terms do not overlap.
 */
export function is_disjoint(left, right) {
  if (left instanceof Positive) {
    if (right instanceof Positive) {
      let r1 = left[0];
      let r2 = right[0];
      return $ranges.is_disjoint(r1, r2);
    } else {
      let p = left[0];
      let n = right[0];
      return $ranges.subset_of(p, n);
    }
  } else if (right instanceof Positive) {
    let n = left[0];
    let p = right[0];
    return $ranges.subset_of(p, n);
  } else {
    return false;
  }
}

/**
 * True if `left` is contained in `right`.
 */
export function subset_of(left, right) {
  if (left instanceof Positive) {
    if (right instanceof Positive) {
      let r1 = left[0];
      let r2 = right[0];
      return $ranges.subset_of(r1, r2);
    } else {
      let r1 = left[0];
      let r2 = right[0];
      return $ranges.is_disjoint(r1, r2);
    }
  } else if (right instanceof Positive) {
    return false;
  } else {
    let r1 = left[0];
    let r2 = right[0];
    return $ranges.subset_of(r2, r1);
  }
}

/**
 * Relation between a term and the intersection of other terms.
 */
export function relation_with(term, other_terms_intersection) {
  let $ = subset_of(other_terms_intersection, term);
  if ($) {
    return new Satisfied();
  } else {
    let $1 = is_disjoint(term, other_terms_intersection);
    if ($1) {
      return new Contradicted();
    } else {
      return new Inconclusive();
    }
  }
}

/**
 * Render a term using a range formatter.
 */
export function to_string(term, range_to_string) {
  if (term instanceof Positive) {
    let set = term[0];
    return range_to_string(set);
  } else {
    let set = term[0];
    return ("Not ( " + range_to_string(set)) + " )";
  }
}
