import * as $g from "../../glance/glance.mjs";
import * as $dict from "../../gleam_stdlib/gleam/dict.mjs";
import { Ok, Error, toList, Empty as $Empty, prepend as listPrepend } from "../gleam.mjs";
import * as $state from "../gloat/state.mjs";
import * as $type_error from "../gloat/type_error.mjs";
import * as $types from "../gloat/types.mjs";

export function ok(value) {
  return $state.pure(new Ok(value));
}

export function error(message, span) {
  return $state.pure(new Error($type_error.new$(message, span)));
}

export function bind(st, f) {
  return $state.bind(
    st,
    (result) => {
      if (result instanceof Ok) {
        let value = result[0];
        return f(value);
      } else {
        let err = result[0];
        return $state.pure(new Error(err));
      }
    },
  );
}

export function map(st, f) {
  return bind(st, (value) => { return ok(f(value)); });
}

export function map_list(list_, f) {
  if (list_ instanceof $Empty) {
    return ok(toList([]));
  } else {
    let one = list_.head;
    let rest = list_.tail;
    return bind(
      f(one),
      (mapped) => {
        return bind(
          map_list(rest, f),
          (rest_mapped) => { return ok(listPrepend(mapped, rest_mapped)); },
        );
      },
    );
  }
}

export function each_list(list_, f) {
  if (list_ instanceof $Empty) {
    return ok(undefined);
  } else {
    let one = list_.head;
    let rest = list_.tail;
    return bind(f(one), (_) => { return each_list(rest, f); });
  }
}

export function foldl_list(list_, init, f) {
  if (list_ instanceof $Empty) {
    return ok(init);
  } else {
    let one = list_.head;
    let rest = list_.tail;
    return bind(f(init, one), (next) => { return foldl_list(rest, next, f); });
  }
}

export function foldr_list(list_, init, f) {
  if (list_ instanceof $Empty) {
    return ok(init);
  } else {
    let one = list_.head;
    let rest = list_.tail;
    return bind(foldr_list(rest, init, f), (next) => { return f(next, one); });
  }
}

export function lift(st) {
  return $state.map(st, (value) => { return new Ok(value); });
}

export function from_result(res) {
  return $state.pure(res);
}

export function run_empty(st) {
  return $state.run_empty(st);
}

export function run_empty_with_hover(st) {
  let $ = $state.run(st, [0, $dict.new$(), $dict.new$()]);
  let data;
  let result;
  data = $[0];
  result = $[1];
  let hover;
  hover = data[2];
  return [result, hover];
}

export function add_hover(span, type_) {
  return lift($state.add_hover(span, type_));
}

export function apply_with(f, arg) {
  return lift($state.apply_with(f, arg));
}
